module TopModule (
    input  logic a,
    input  logic b,
    input  logic c,
    input  logic d,
    output logic out_sop,
    output logic out_pos
);

  assign out_sop = (c & d) | (~a & ~b & c);
  assign out_pos = c & (~a | b) & (~b | d);

endmodule

module tb_TopModule;
  logic a, b, c, d;
  logic out_sop, out_pos;

  TopModule uut (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .out_sop(out_sop),
    .out_pos(out_pos)
  );

  initial begin
    integer i;
    logic [3:0] expected_val;
    // Expected values for 0..15 (-1 means don't care)
    // 0:0, 1:0, 2:1, 3:X, 4:0, 5:0, 6:0, 7:1, 8:X, 9:0, 10:0, 11:X, 12:X, 13:0, 14:0, 15:1

    for (i = 0; i < 16; i++) begin
      {a, b, c, d} = i[3:0];
      #1;

      // Check specified exact values
      case (i)
        0, 1, 4, 5, 6, 9, 10, 13, 14: begin
          if (out_sop !== 1'b0) begin
            $display("FAIL: input %0d (0000..1111 = %b) expected out_sop = 0, got %b", i, i[3:0], out_sop);
            $finish;
          end
          if (out_pos !== 1'b0) begin
            $display("FAIL: input %0d (0000..1111 = %b) expected out_pos = 0, got %b", i, i[3:0], out_pos);
            $finish;
          end
        end
        2, 7, 15: begin
          if (out_sop !== 1'b1) begin
            $display("FAIL: input %0d (0000..1111 = %b) expected out_sop = 1, got %b", i, i[3:0], out_sop);
            $finish;
          end
          if (out_pos !== 1'b1) begin
            $display("FAIL: input %0d (0000..1111 = %b) expected out_pos = 1, got %b", i, i[3:0], out_pos);
            $finish;
          end
        end
        default: begin
          // Don't care conditions: 3, 8, 11, 12
          // Just verify they output 0 or 1 without error
          $display("INFO: Don't care input %0d tested: sop=%b, pos=%b", i, out_sop, out_pos);
        end
      endcase
    end

    $display("SELFTEST PASS");
    $finish;
  end

endmodule
